"""Zero-Token Direct Patcher (scripts/apply_direct_fixes.py)."""

import base64
import json
import shutil
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
PAYLOAD_B64 = ""


def apply_all() -> None:
    bundle = json.loads(zlib.decompress(base64.b64decode(PAYLOAD_B64)).decode("utf-8"))
    updated = []
    for rel_path, content in bundle.items():
        target = ROOT / rel_path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        updated.append(rel_path)

    models_dir = ROOT / "data_persistence" / "models"
    legacy_dir = models_dir / "legacy_unverified"
    models_dir.mkdir(parents=True, exist_ok=True)
    legacy_dir.mkdir(parents=True, exist_ok=True)
    mapping = {
        "crypto_lgbm_weights.joblib": "crypto_lgbm_manifest.json",
        "crypto_ppo_agent.pt": "crypto_ppo_manifest.json",
        "taiwan_stock_ranker.joblib": "taiwan_stock_manifest.json",
    }
    quarantined = []
    for m_file, mf_file in mapping.items():
        mp = models_dir / m_file
        mfp = models_dir / mf_file
        alt_mfp = models_dir / (Path(m_file).stem + "_manifest.json")
        if mp.exists() and not (mfp.exists() or alt_mfp.exists()):
            shutil.move(str(mp), str(legacy_dir / f"{m_file}.unverified"))
            quarantined.append(m_file)

    print(f"[OK] Applied direct verified upgrades to {len(updated)} files.")
    if quarantined:
        print(f"[OK] Quarantined unverified synthetic models: {quarantined}")


if __name__ == "__main__":
    apply_all()
